class stringx
{
    void *chars;
    void *my_buf;
};

class FEMenu;

class FEMenuEntry
{
public:
    int entry_num;
    FEMenuEntry *next;
    FEMenuEntry *previous;
    FEMenu *menu;
    char fields[0x44];

    virtual ~FEMenuEntry();
    virtual void Load();
    virtual void OnSelect();
    virtual void Highlight(bool, bool);
    virtual void Disable(bool);
    virtual bool GetDisable();
    virtual void Draw();
    virtual void Update(float);
    virtual void TurnOn(bool);
    virtual void SetSpecialColor(unsigned int, unsigned int);
    virtual void SetSpecialScale(float, float);
    virtual bool GetSpecialScale(float &, float &);
    virtual void SetNoFlash(bool);
    virtual float GetHighlightIntensity();
    virtual void SetPos(float, float);
};

class FEMenu
{
public:
    int center_x;
    int center_y;
    int num_entries;
    int dy;
    int half;
    int menu_num;
    bool init;
    stringx font_filename;
    unsigned int color;
    unsigned int color_high;
    unsigned int color_high_alt;
    float scale;
    float scale_high;
    int max_vis_entries;
    int flags;
    FEMenuEntry *entries;
    FEMenuEntry *first_vis_entry;
    FEMenuEntry *last_vis_entry;
    FEMenuEntry *highlighted;
    void *system;
    FEMenu *back;
    int back_num;
    FEMenu *submenus;
    FEMenu *active;
    FEMenu *parent;
    void *helpText;
    int helpFlags;
    FEMenu *next_sub;

    virtual ~FEMenu();
    virtual void setBack(FEMenu *, int);
    virtual void setHigh(FEMenuEntry *, bool);
    virtual void setVis(FEMenuEntry *);
    virtual void Add(FEMenuEntry *);
    virtual void Init();
};

enum
{
    FEMENU_SCROLLING = 0x001,
    FEMENU_DONT_SHOW_DISABLED = 0x400
};

void FEMenu::Init()
{
	if(num_entries > max_vis_entries) flags |= FEMENU_SCROLLING;
	if(flags & FEMENU_SCROLLING) half = (dy * (max_vis_entries-1))/2;
	else if(flags & FEMENU_DONT_SHOW_DISABLED)
	{
		// count up non-disabled entries
		int count = 0;
		FEMenuEntry* tmp = entries;
		while(tmp != 0)
		{
			if(!tmp->GetDisable()) count++;
			tmp = tmp->next;
		}
		half = (dy * (count-1))/2;
	}
	else half = (dy * (num_entries-1))/2;


	if (entries)
		setHigh(entries, false);
	init = true;

	if(flags & FEMENU_SCROLLING) setVis(entries);
	else
	{
		int y;
		FEMenuEntry* tmp = entries;
		int index = 0;
		while(tmp != 0)
		{
			if(!(flags & FEMENU_DONT_SHOW_DISABLED) || !tmp->GetDisable())
			{
				y = center_y + index * dy - half;
				tmp->SetPos(center_x, y);
				index++;
			}
			tmp = tmp->next;
		}
	}
}
